`, "",{"version":3,"sources":["webpack://./src/我的机娘是世界级的/脚本/共鸣技能/App.vue"],"names":[],"mappings":"AAwKA,kCACE,cAAe,CACf,OAAQ,CACR,aAAc,CACd,mBAAoB,CACpB,sGAAgH,CAChH,SAAU,CACV,4BACF,CAEA,+CACE,6CACF,CAEA,mCACE,GACE,SACF,CACA,GACE,SAAU,CACV,4HAOF,CACA,IACE,WACF,CACA,IACE,WAAY,CACZ,uGAMF,CACA,IACE,WACF,CACA,IACE,WAAY,CACZ,sGAMF,CACA,IACE,WACF,CACA,IACE,YACF,CACA,KACE,SACF,CACF,CAGA,oCACE,cAAe,CACf,OAAQ,CACR,aAAc,CACd,YAAa,CACb,kBAAmB,CACnB,sBAAuB,CACvB,0BAA8B,CAC9B,yBACF,CAGA,kCACE,iBAAkB,CAClB,WAAY,CACZ,cAAe,CACf,sEAA0E,CAC1E,qCAAyC,CACzC,kIAA0I,CAC1I,iBAAkB,CAClB,iBAAkB,CAClB,0GAGwC,CACxC,eACF,CAGA,qEAEE,iBAAkB,CAClB,QAAS,CACT,SAAU,CACV,UAAW,CACX,iFAAuF,CACvF,oDACF,CAEA,iCACE,KACF,CAEA,oCACE,QACF,CAEA,8BACE,QAEE,WACF,CACA,IACE,SACF,CACF,CAGA,6BACE,kBAAmB,CACnB,8CACF,CAEA,6BACE,GACE,sBACF,CACA,KACE,wBACF,CACF,CAGA,8BACE,gDAAmD,CACnD,cAAe,CACf,eAAgB,CAChB,kBAAmB,CACnB,wBAAyB,CACzB,2BAA+B,CAC/B,kBACF,CAGA,kCACE,gDAAmD,CACnD,cAAe,CACf,eAAgB,CAChB,UAAW,CACX,iBAAkB,CAClB,yCACF,CAGA,mCACE,cAAe,CACf,eAAgB,CAChB,0DAA8D,CAC9D,oBAAqB,CACrB,4BAA6B,CAC7B,mCAAoC,CACpC,iBAAkB,CAClB,uDACF,CAEA,iCACE,QAEE,oBACF,CACA,IACE,sBACF,CACF,CAGA,mCACE,cAAe,CACf,2BAA+B,CAC/B,eAAgB,CAChB,kBAAmB,CACnB,aACF,CAGA,gCACE,YAAa,CACb,QAAS,CACT,sBACF,CAEA,+BACE,mBAAoB,CACpB,kBAAmB,CACnB,sBAAuB,CACvB,iBAAkB,CAClB,kDAAqD,CACrD,UAAW,CACX,WAAY,CACZ,cAAe,CACf,eAAgB,CAChB,cAAe,CACf,kIAA0I,CAC1I,wBAAyB,CACzB,qCACF,CAEA,qCACE,kDAAqD,CACrD,wCAA4C,CAC5C,0BACF,CAEA,sCACE,uBACF,CAEA,8BACE,iBAAkB,CAClB,sBAAuB,CACvB,2BAA+B,CAC/B,uCAA2C,CAC3C,cAAe,CACf,cAAe,CACf,kIAA0I,CAC1I,wBACF,CAEA,oCACE,2BAA+B,CAC/B,kCACF,CAGA,+CACE,kDACF,CAEA,+CACE,4BACF,CAEA,6CACE,SAAU,CACV,qBACF,CAEA,2CACE,SAAU,CACV,qBACF","sourcesContent":["<template>\n  <!-- 全屏闪烁遮罩 -->\n  <div v-if=\"showFlash\" class=\"resonance-flash\" :class=\"{ 'flash-active': flashActive }\"></div>\n\n  <!-- 共鸣技能确认弹窗 -->\n  <Teleport :to=\"hostBody\">\n    <Transition name=\"resonance-modal\">\n      <div v-if=\"showModal\" class=\"resonance-overlay\" @click.self=\"dismiss\">\n        <div class=\"resonance-modal\">\n          <!-- 顶部光条 -->\n          <div class=\"modal-glow-top\"></div>\n\n          <!-- 共鸣图标 -->\n          <div class=\"modal-icon\">\n            <svg viewBox=\"0 0 64 64\" width=\"56\" height=\"56\">\n              <circle cx=\"32\" cy=\"32\" r=\"28\" fill=\"none\" stroke=\"url(#resonanceGrad)\" stroke-width=\"3\" />\n              <path\n                d=\"M32 12 L36 28 L52 32 L36 36 L32 52 L28 36 L12 32 L28 28 Z\"\n                fill=\"url(#resonanceGrad)\"\n                opacity=\"0.9\"\n              />\n              <defs>\n                <linearGradient id=\"resonanceGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                  <stop offset=\"0%\" stop-color=\"#6366f1\" />\n                  <stop offset=\"50%\" stop-color=\"#06b6d4\" />\n                  <stop offset=\"100%\" stop-color=\"#f59e0b\" />\n                </linearGradient>\n              </defs>\n            </svg>\n          </div>\n\n          <!-- 标题 -->\n          <div class=\"modal-title\">共鸣技能就绪</div>\n\n          <!-- 机娘名 + 技能名 -->\n          <div class=\"modal-mech-name\">{{ partnerName }}</div>\n          <div class=\"modal-skill-name\">「{{ skillName }}」</div>\n          <div class=\"modal-skill-desc\">{{ skillDesc }}</div>\n\n          <!-- 按钮组 -->\n          <div class=\"modal-buttons\">\n            <button class=\"btn-activate\" @click=\"activateSkill\">\n              <svg viewBox=\"0 0 20 20\" width=\"16\" height=\"16\" style=\"margin-right: 6px\">\n                <polygon points=\"3,1 17,10 3,19\" fill=\"currentColor\" />\n              </svg>\n              发动共鸣\n            </button>\n            <button class=\"btn-dismiss\" @click=\"dismiss\">暂不使用</button>\n          </div>\n\n          <!-- 底部光条 -->\n          <div class=\"modal-glow-bottom\"></div>\n        </div>\n      </div>\n    </Transition>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { Schema } from '../../schema';\n\nconst hostBody = window.parent.document.body;\n\nconst showFlash = ref(false);\nconst flashActive = ref(false);\nconst showModal = ref(false);\n\nconst partnerName = ref('');\nconst skillName = ref('');\nconst skillDesc = ref('');\n\n// 已经触发过的搭档机娘名（防止同一机娘重复触发）\nconst triggeredSet = new Set<string>();\n\n// 检测共鸣值\nfunction checkResonance() {\n  const raw = Mvu.getMvuData({ type: 'message', message_id: -1 });\n  const data = Schema.parse(_.get(raw, 'stat_data'));\n\n  // 只在比赛中检测\n  if (data.世界._当前状态 !== '比赛中') return;\n\n  const partner = data.当前比赛._搭档机娘;\n  if (!partner) return;\n\n  const mech = data.机娘库[partner];\n  if (!mech) return;\n\n  const resonance = mech.共鸣;\n  if (!resonance.已激活) return;\n  if (resonance.当前共鸣值 < 100) return;\n\n  // 防止重复触发\n  if (triggeredSet.has(partner)) return;\n  triggeredSet.add(partner);\n\n  // 触发共鸣效果\n  partnerName.value = partner;\n  skillName.value = resonance.技能名;\n  skillDesc.value = resonance.技能描述;\n  triggerFlashAndModal();\n}\n\n// 触发闪烁 + 弹窗\nfunction triggerFlashAndModal() {\n  showFlash.value = true;\n  flashActive.value = false;\n\n  // 启动闪烁动画\n  requestAnimationFrame(() => {\n    flashActive.value = true;\n  });\n\n  // 闪烁持续 1.5s 后显示弹窗\n  setTimeout(() => {\n    showModal.value = true;\n  }, 800);\n\n  // 闪烁 2s 后渐隐\n  setTimeout(() => {\n    flashActive.value = false;\n    setTimeout(() => {\n      showFlash.value = false;\n    }, 500);\n  }, 2000);\n}\n\n// 发动共鸣技能\nasync function activateSkill() {\n  showModal.value = false;\n\n  // 注入提示词告知 AI 共鸣技能被发动\n  const injectText = `[系统提示] 车手发动了搭档机娘「${partnerName.value}」的共鸣技能「${skillName.value}」！技能效果：${skillDesc.value}。共鸣值归零，请在接下来的回复中体现共鸣技能的发动效果和对赛况的影响。`;\n\n  injectPrompts(\n    [\n      {\n        id: `resonance-skill-${Date.now()}`,\n        position: 'in_chat',\n        depth: 0,\n        role: 'system',\n        content: injectText,\n        should_scan: false,\n      },\n    ],\n    { once: true },\n  );\n\n  toastr.success(`共鸣技能「${skillName.value}」已发动！`, partnerName.value);\n}\n\n// 暂不使用\nfunction dismiss() {\n  showModal.value = false;\n  // 移除已触发标记，允许下次再触发\n  triggeredSet.delete(partnerName.value);\n}\n\n// 监听 MVU 变量更新\nonMounted(() => {\n  eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {\n    checkResonance();\n  });\n});\n</script>\n\n<style scoped>\n/* ===== 全屏闪烁遮罩 ===== */\n.resonance-flash {\n  position: fixed;\n  inset: 0;\n  z-index: 99998;\n  pointer-events: none;\n  background: radial-gradient(ellipse at center, rgba(99, 102, 241, 0.3), rgba(6, 182, 212, 0.2), transparent 70%);\n  opacity: 0;\n  transition: opacity 0.5s ease;\n}\n\n.resonance-flash.flash-active {\n  animation: resonanceFlash 2s ease-out;\n}\n\n@keyframes resonanceFlash {\n  0% {\n    opacity: 0;\n  }\n  8% {\n    opacity: 1;\n    background: radial-gradient(\n      ellipse at center,\n      rgba(255, 255, 255, 0.9),\n      rgba(99, 102, 241, 0.6),\n      rgba(6, 182, 212, 0.3),\n      transparent 80%\n    );\n  }\n  15% {\n    opacity: 0.3;\n  }\n  25% {\n    opacity: 0.9;\n    background: radial-gradient(\n      ellipse at center,\n      rgba(245, 158, 11, 0.7),\n      rgba(99, 102, 241, 0.5),\n      transparent 70%\n    );\n  }\n  35% {\n    opacity: 0.2;\n  }\n  45% {\n    opacity: 0.7;\n    background: radial-gradient(\n      ellipse at center,\n      rgba(6, 182, 212, 0.6),\n      rgba(99, 102, 241, 0.4),\n      transparent 70%\n    );\n  }\n  60% {\n    opacity: 0.4;\n  }\n  75% {\n    opacity: 0.15;\n  }\n  100% {\n    opacity: 0;\n  }\n}\n\n/* ===== 弹窗遮罩 ===== */\n.resonance-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 99999;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  background: rgba(0, 0, 0, 0.6);\n  backdrop-filter: blur(4px);\n}\n\n/* ===== 弹窗主体 ===== */\n.resonance-modal {\n  position: relative;\n  width: 360px;\n  max-width: 90vw;\n  background: linear-gradient(145deg, #1a1a2e 0%, #16213e 50%, #0f1729 100%);\n  border: 1px solid rgba(99, 102, 241, 0.4);\n  clip-path: polygon(0 8px, 8px 0, calc(100% - 8px) 0, 100% 8px, 100% calc(100% - 8px), calc(100% - 8px) 100%, 8px 100%, 0 calc(100% - 8px));\n  padding: 32px 28px;\n  text-align: center;\n  box-shadow:\n    0 0 40px rgba(99, 102, 241, 0.3),\n    0 0 80px rgba(6, 182, 212, 0.15),\n    inset 0 1px 0 rgba(255, 255, 255, 0.1);\n  overflow: hidden;\n}\n\n/* 顶部/底部光条 */\n.modal-glow-top,\n.modal-glow-bottom {\n  position: absolute;\n  left: 10%;\n  right: 10%;\n  height: 2px;\n  background: linear-gradient(90deg, transparent, #6366f1, #06b6d4, #f59e0b, transparent);\n  animation: glowPulse 2s ease-in-out infinite;\n}\n\n.modal-glow-top {\n  top: 0;\n}\n\n.modal-glow-bottom {\n  bottom: 0;\n}\n\n@keyframes glowPulse {\n  0%,\n  100% {\n    opacity: 0.6;\n  }\n  50% {\n    opacity: 1;\n  }\n}\n\n/* 共鸣图标 */\n.modal-icon {\n  margin-bottom: 16px;\n  animation: iconSpin 4s linear infinite;\n}\n\n@keyframes iconSpin {\n  0% {\n    transform: rotate(0deg);\n  }\n  100% {\n    transform: rotate(360deg);\n  }\n}\n\n/* 标题 */\n.modal-title {\n  font-family: 'Rajdhani', 'Noto Sans SC', sans-serif;\n  font-size: 13px;\n  font-weight: 600;\n  letter-spacing: 4px;\n  text-transform: uppercase;\n  color: rgba(255, 255, 255, 0.5);\n  margin-bottom: 12px;\n}\n\n/* 机娘名 */\n.modal-mech-name {\n  font-family: 'Rajdhani', 'Noto Sans SC', sans-serif;\n  font-size: 22px;\n  font-weight: 700;\n  color: #fff;\n  margin-bottom: 4px;\n  text-shadow: 0 0 12px rgba(99, 102, 241, 0.6);\n}\n\n/* 技能名 */\n.modal-skill-name {\n  font-size: 28px;\n  font-weight: 700;\n  background: linear-gradient(135deg, #6366f1, #06b6d4, #f59e0b);\n  background-clip: text;\n  -webkit-background-clip: text;\n  -webkit-text-fill-color: transparent;\n  margin-bottom: 8px;\n  animation: skillShimmer 3s ease-in-out infinite;\n}\n\n@keyframes skillShimmer {\n  0%,\n  100% {\n    filter: brightness(1);\n  }\n  50% {\n    filter: brightness(1.3);\n  }\n}\n\n/* 技能描述 */\n.modal-skill-desc {\n  font-size: 13px;\n  color: rgba(255, 255, 255, 0.6);\n  line-height: 1.6;\n  margin-bottom: 24px;\n  padding: 0 8px;\n}\n\n/* 按钮组 */\n.modal-buttons {\n  display: flex;\n  gap: 12px;\n  justify-content: center;\n}\n\n.btn-activate {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  padding: 10px 28px;\n  background: linear-gradient(135deg, #6366f1, #4f46e5);\n  color: #fff;\n  border: none;\n  font-size: 15px;\n  font-weight: 600;\n  cursor: pointer;\n  clip-path: polygon(0 4px, 4px 0, calc(100% - 4px) 0, 100% 4px, 100% calc(100% - 4px), calc(100% - 4px) 100%, 4px 100%, 0 calc(100% - 4px));\n  transition: all 0.2s ease;\n  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.3);\n}\n\n.btn-activate:hover {\n  background: linear-gradient(135deg, #818cf8, #6366f1);\n  box-shadow: 0 0 20px rgba(99, 102, 241, 0.5);\n  transform: translateY(-1px);\n}\n\n.btn-activate:active {\n  transform: translateY(0);\n}\n\n.btn-dismiss {\n  padding: 10px 20px;\n  background: transparent;\n  color: rgba(255, 255, 255, 0.5);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n  font-size: 14px;\n  cursor: pointer;\n  clip-path: polygon(0 4px, 4px 0, calc(100% - 4px) 0, 100% 4px, 100% calc(100% - 4px), calc(100% - 4px) 100%, 4px 100%, 0 calc(100% - 4px));\n  transition: all 0.2s ease;\n}\n\n.btn-dismiss:hover {\n  color: rgba(255, 255, 255, 0.8);\n  border-color: rgba(255, 255, 255, 0.3);\n}\n\n/* ===== 弹窗过渡动画 ===== */\n.resonance-modal-enter-active {\n  transition: all 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);\n}\n\n.resonance-modal-leave-active {\n  transition: all 0.25s ease-in;\n}\n\n.resonance-modal-enter-from {\n  opacity: 0;\n  transform: scale(0.85);\n}\n\n.resonance-modal-leave-to {\n  opacity: 0;\n  transform: scale(0.95);\n}\n</style>\n"],"sourceRoot":""}]);
